    o.a
}

// Cayley-Dickson multiplication (verified for norm multiplicativity and Moufang identities)
fn oct_mul(a: Octonion, b: Octonion) -> Octonion {
    let c0 = a.a*b.a - a.b*b.b - a.c*b.c - a.d*b.d - a.e*b.e - a.f*b.f - a.g*b.g - a.h*b.h
