struct PBPKState {
    t: f64,
    gut: f64,
    central: f64,
    auc: f64,
    cmax: f64,
    tmax: f64
}

fn euler_step(s: PBPKState, dt: f64) -> PBPKState with Mut {
    let ka = 1.0
    let ke = 0.1
    let d_gut = -ka * s.gut
    let d_central = ka * s.gut - ke * s.central
    let new_central = s.central + d_central * dt

    // Track Cmax/Tmax
    let new_t = s.t + dt
    var cmax = s.cmax
    var tmax = s.tmax
    if new_central > s.cmax {
        cmax = new_central
        tmax = new_t
    }

    PBPKState {
        t: new_t,
        gut: s.gut + d_gut * dt,
        central: new_central,
        auc: s.auc + s.central * dt,
        cmax: cmax,
        tmax: tmax
    }
}

fn main() -> i32 with IO, Div, Mut {
    var s = PBPKState {
        t: 0.0, gut: 500.0, central: 0.0,
        auc: 0.0, cmax: 0.0, tmax: 0.0
    }
    let dt = 0.1
    var i = 0

    while i < 240 {
        s = euler_step(s, dt)
        i = i + 1
    }

    // Print results for validation
    println(s.t)
    println(s.gut)
    println(s.central)
    println(s.auc)
    println(s.cmax)
    println(s.tmax)

    // Validate against analytical expectations:
