            var sf: f64 = 1.0
            if s < 0 { sf = 0.0 - 1.0 }
            let v = sf * OA[i]
            let w = v * OB[j]
            OC[tgt] = OC[tgt] + w
            j = j + 1
        }
        i = i + 1
    }
}

fn oct_norm_global_c() -> f64 with Mut {
