fn exp_neg(x: f64) -> f64 with Mut, Div {
    if x == 0.0 { return 1.0 }
    var s = x;
    var k = 0;
    while s < (0.0 - 0.5) {
        s = s * 0.5;
        k = k + 1;
    }
    let s2 = s * s;
    let s3 = s2 * s;
    let s4 = s2 * s2;
    let s5 = s4 * s;
