use math::octonion::*

fn test_octonion_construction() with IO {
    // Create an octonion: 1 + 0.5i + 0.3j + 0.2k + 0.1l + 0.15il + 0.25jl + 0.05kl
    let o = oct(1.0, 0.5, 0.3, 0.2, 0.1, 0.15, 0.25, 0.05)

