fn reverse_bits(n: i64) -> f64 with Mut {
    var result: f64 = 0.0;
    var v = n;
    var b: f64 = 0.5;
    while v > 0 {
        if (v % 2) == 1 { result = result + b }
        v = v / 2;
        b = b / 2.0;
    }
    return result;
