use algebra::octonion::{cd_sigma, oct_xor, oct_mul, oct_norm_sq, oct_basis, oct_associator, is_fano_triple}

fn fano_line_i(n: i64) -> i64 {
    if n == 0 { return 1 }
    if n == 1 { return 1 }
    if n == 2 { return 1 }
    if n == 3 { return 2 }
    if n == 4 { return 2 }
    if n == 5 { return 3 }
    3
}

fn fano_line_j(n: i64) -> i64 {
    if n == 0 { return 2 }
    if n == 1 { return 4 }
    if n == 2 { return 7 }
    if n == 3 { return 4 }
    if n == 4 { return 5 }
    if n == 5 { return 4 }
    6
}

fn fano_line_k(n: i64) -> i64 {
    if n == 0 { return 3 }
    if n == 1 { return 5 }
    if n == 2 { return 6 }
    if n == 3 { return 6 }
    if n == 4 { return 7 }
    if n == 5 { return 7 }
    5
}

fn basis_assoc_norm_sq(i: i64, j: i64, k: i64) -> f64 with Mut, Div, NonAssoc {
    var a = oct_basis(i)
    var b = oct_basis(j)
    var c = oct_basis(k)
    var assoc: [f64; 8] = [0.0; 8]
    oct_associator(&a, &b, &c, &!assoc)
    oct_norm_sq(&assoc)
}

fn su3_block(k: i64) -> i64 {
    if k < 3 { return 0 }
    if k < 6 { return 1 }
    2
}

fn su3_quality_identity() -> f64 with Mut {
    var total = 0.0
    var off = 0.0
    var i: i64 = 0
    while i < 7 {
        var j: i64 = 0
        while j < 7 {
            var val = 0.0
            if i == j { val = 1.0 }
            total = total + val * val
            if su3_block(i) != su3_block(j) { off = off + val * val }
            j = j + 1
        }
        i = i + 1
    }
    1.0 - off / total
}

fn su3_quality_scrambled() -> f64 with Mut {
    var total = 0.0
    var off = 0.0
    var i: i64 = 0
    while i < 7 {
        var j: i64 = 0
        while j < 7 {
            var val = 0.0
            if i == j { val = 1.0 }
            if i == 0 && j == 3 { val = 0.5 }
            if i == 3 && j == 0 { val = 0.5 }
            total = total + val * val
            if su3_block(i) != su3_block(j) { off = off + val * val }
            j = j + 1
        }
        i = i + 1
    }
    1.0 - off / total
}

fn main() -> i32 with IO, Mut, Div, NonAssoc {
    var pass: i32 = 0
    var line: i64 = 0
    while line < 7 {
