    // For o = 3 + 4i, norm_sq = 9 + 16 = 25, norm = 5
    let norm_sq = oct_norm_sq(o)
    let norm = oct_norm(o)

    print("Test 2: Norm Operations")
    print("Octonion: 3 + 4i")
    print("Expected norm_sq = 25.0")
    print("Expected norm = 5.0")

