    let dp: f64 = f2_paired_dist_sq(&t)
    let dr: f64 = f2_random_dist_sq(&t)
    var r: f64 = 0.0
    if dp > 0.0000000001 { r = dr / dp }

    var ok: i64 = 1
    if r < 5.0 { ok = 0 }
    if dp > 0.10 { ok = 0 }
    if dp <= 0.0 { ok = 0 }

    if ok == 1 {
        print("PASS\n")
    } else {
        print("FAIL\n")
    }
    return 0
}

