//@ run-pass
//! Minimal octonion test - pure Sounio, no stdlib dependencies

struct Octonion {
    a: f32,
    b: f32,
    c: f32,
    d: f32,
    e: f32,
    f: f32,
    g: f32,
    h: f32
}

// Newton's method sqrt - functional style to avoid var
fn sqrt_f32(x: f32) -> f32 {
    if x <= 0.0 {
        0.0
    } else {
        let y1 = x
        let y2 = 0.5 * (y1 + x / y1)
        let y3 = 0.5 * (y2 + x / y2)
        let y4 = 0.5 * (y3 + x / y3)
        let y5 = 0.5 * (y4 + x / y4)
        y5
    }
}

fn oct(a: f32, b: f32, c: f32, d: f32, e: f32, f: f32, g: f32, h: f32) -> Octonion {
    Octonion { a: a, b: b, c: c, d: d, e: e, f: f, g: g, h: h }
}

fn oct_norm_sq(o: Octonion) -> f32 {
    o.a * o.a + o.b * o.b + o.c * o.c + o.d * o.d +
    o.e * o.e + o.f * o.f + o.g * o.g + o.h * o.h
}

fn oct_norm(o: Octonion) -> f32 {
    sqrt_f32(oct_norm_sq(o))
