    // We can verify by checking that the real part is preserved
    let real_part = oct_real(o_relu)

    if real_part > 0.99 && real_part < 1.01 {
        print("✓ ReLU preserves positive real part")
    }
}

fn test_zero_octonion() with IO, Panic {
