    print("Octonion Basic Demo")
    print("===================")

    // Create octonion from 8 components
    // o = a + bi + cj + dk + el + fil + gjl + hkl
    let o = oct(
        1.0,  // a (real part)
        0.5,  // b (i)
        0.3,  // c (j)
        0.2,  // d (k)
