    let ref_wt = make_knowledge(70.0, 0.1, 1.0)
    let weight_factor = gum_div(weight, ref_wt)
    let dose1 = gum_mul(base_dose, weight_factor)

    println("Step 1  weight-adjusted dose")
    println(dose1.value)
