    let ka = 1.0;
    let ke = 0.1;
    let d_gut = -ka * s.gut;
    let d_central = ka * s.gut - ke * s.central;
    let new_central = s.central + d_central * dt;

    // Track Cmax/Tmax
    let new_t = s.t + dt;
    var cmax = s.cmax;
    var tmax = s.tmax;
    if new_central > s.cmax {
        cmax = new_central;
        tmax = new_t;
    }

    PBPKState {
        t: new_t,
        gut: s.gut + d_gut * dt,
        central: new_central,
        auc: s.auc + s.central * dt,
        cmax: cmax,
        tmax: tmax;
    }
}

fn main() -> i32 with IO, Div, Mut {
